import sys

def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except ValueError:
        return

    if n <= 0:
        print("impossible")
        return

    # We need m^2 - k^2 = n  => (m-k)(m+k) = n
    # Let a = m-k, b = m+k, then a*b = n and b > a, and a, b have same parity.
    # Then m = (a+b)//2, k = (b-a)//2
    # Since m and k must be integers, a and b must be both even or both odd.
    # Also k >= 0 => b >= a.
    # Iterate a from 1 to sqrt(n). If a divides n, check parity and compute m, k.

    limit = int(n ** 0.5) + 1
    for a in range(1, limit):
        if n % a == 0:
            b = n // a
            # Ensure a <= b (since a is the smaller factor)
            if a > b:
                continue
            # Check parity: (a and b) must be both even or both odd
            if (a % 2) == (b % 2):
                m = (a + b) // 2
                k = (b - a) // 2
                if k >= 0:
                    print(m, k)
                    return

    print("impossible")

if __name__ == "__main__":
    solve()
